begin;
do $test$
declare
 admin_v uuid:='00000000-0000-4000-8000-000000000111';
 sid uuid:=gen_random_uuid(); iid uuid:=gen_random_uuid(); req uuid:=gen_random_uuid(); rfq uuid:=gen_random_uuid(); ri uuid:=gen_random_uuid(); inv uuid:=gen_random_uuid();
 token text:=repeat('e',64); challenge uuid:=gen_random_uuid(); challenge2 uuid:=gen_random_uuid(); result jsonb; lid uuid; n integer;
begin
 perform set_config('request.jwt.claim.sub',admin_v::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 insert into public.proc_items(id,item_code,category,description,uom,max_stock,reorder_level,movement) values(iid,'OTP-QA','GENERAL','OTP fixture','PCS',20,10,'FAST');
 insert into public.proc_suppliers(id,supplier_code,name,whatsapp,active) values(sid,'OTP-QA','OTP supplier','0771234567',true);
 insert into public.proc_requirements(id,requirement_no,item_id,location_id,required_qty,adjusted_qty,approval_status,created_by,source_type)
 values(req,'OTP-QA-REQ',iid,private.proc_default_location_id(),10,10,'approved',admin_v,'manual');
 insert into public.proc_rfqs(id,rfq_no,status,created_by) values(rfq,'OTP-QA-RFQ','prepared',admin_v);
 insert into public.proc_rfq_items(id,rfq_id,requirement_id,requested_qty) values(ri,rfq,req,10);
 insert into public.proc_rfq_suppliers(id,rfq_id,supplier_id,requested_item_ids) values(inv,rfq,sid,array[ri]);
 result:=public.proc_portal_issue_link_v1(inv,encode(extensions.digest(token,'sha256'),'hex'),6);lid:=(result->>'link_id')::uuid;
 execute 'set local role anon';
 begin perform public.proc_portal_read_v1(token);raise exception 'TEST bearer-only read';exception when insufficient_privilege then null;end;
 begin perform public.proc_portal_submit_v1(token,'[]',0,false);raise exception 'TEST bearer-only write';exception when insufficient_privilege then null;end;
 begin perform public.proc_portal_otp_request_v1(token,'0771234567',challenge,repeat('a',64));raise exception 'TEST browser requests privileged challenge';exception when insufficient_privilege then null;end;
 begin perform public.proc_supplier_document_settings_v1();raise exception 'TEST anonymous templates';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','service_role',true);
 assert private.proc_portal_phone_v1('+94 77 123 4567')='94771234567';
 assert private.proc_portal_phone_v1('0094771234567')='94771234567';
 assert private.proc_portal_phone_v1('0811234567') is null;
 assert public.proc_portal_otp_request_v1(token,'0771234568',challenge,repeat('a',64)) is null,'Wrong supplier number accepted';
 result:=public.proc_portal_otp_request_v1(token,'+94 77 123 4567',challenge,repeat('a',64));
 assert result->>'phone'='94771234567','Recipient not from registered number';
 assert public.proc_portal_otp_request_v1(token,'0771234567',challenge2,repeat('b',64))->>'limited'='true','Resend cooldown bypassed';
 assert public.proc_portal_otp_verify_v1(token,challenge,repeat('a',64),repeat('c',64)) is null,'Undelivered code accepted';
 assert public.proc_portal_otp_delivered_v1(challenge);
 for n in 1..5 loop
  assert public.proc_portal_otp_verify_v1(token,challenge,repeat('b',64),repeat('c',64)) is null,'Wrong code accepted';
 end loop;
 assert (select attempts from private.proc_portal_otp_challenges where id=challenge)=5,'Wrong attempts rolled back';
 assert public.proc_portal_otp_verify_v1(token,challenge,repeat('a',64),repeat('c',64)) is null,'Attempt limit bypassed';
 update private.proc_portal_otp_limits set last_at=clock_timestamp()-interval '2 minutes';
 update private.proc_portal_otp_limits set sent=5;
 assert public.proc_portal_otp_request_v1(token,'0771234567',challenge2,repeat('a',64))->>'limited'='true','Hourly send limit bypassed';
 update private.proc_portal_otp_limits set sent=1;
 result:=public.proc_portal_otp_request_v1(token,'0771234567',challenge2,repeat('a',64));
 assert public.proc_portal_otp_delivered_v1(challenge2);
 assert public.proc_portal_otp_verify_v1(token,challenge,repeat('a',64),repeat('c',64)) is null,'Replaced code accepted';
 update private.proc_portal_otp_challenges set expires_at=clock_timestamp()-interval '1 second' where id=challenge2;
 assert public.proc_portal_otp_verify_v1(token,challenge2,repeat('a',64),repeat('c',64)) is null,'Expired code accepted';
 update private.proc_portal_otp_challenges set expires_at=clock_timestamp()+interval '4 minutes' where id=challenge2;
 result:=public.proc_portal_otp_verify_v1(token,challenge2,repeat('a',64),repeat('c',64));
 assert result->>'expires_at' is not null;
 assert public.proc_portal_otp_verify_v1(token,challenge2,repeat('a',64),repeat('d',64)) is null,'OTP replay accepted';
 assert jsonb_array_length(public.proc_portal_session_v1(token,repeat('c',64),'read')->'items')=1;
 assert public.proc_portal_session_v1(token,repeat('c',64),'submit','[]',0,false)->>'revision'='1','Verified draft save failed';
 begin perform public.proc_portal_session_v1(token,repeat('d',64),'read');raise exception 'TEST forged session';exception when insufficient_privilege then null;end;
 update private.proc_portal_otp_sessions set expires_at=clock_timestamp()-interval '1 second';
 begin perform public.proc_portal_session_v1(token,repeat('c',64),'read');raise exception 'TEST expired session';exception when insufficient_privilege then null;end;
 update private.proc_portal_otp_sessions set expires_at=clock_timestamp()+interval '1 hour';
 perform set_config('request.jwt.claim.sub',admin_v::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 update public.proc_suppliers set whatsapp='0771234568' where id=sid;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','service_role',true);
 begin perform public.proc_portal_session_v1(token,repeat('c',64),'read');raise exception 'TEST changed phone retains session';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_v::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 update public.proc_suppliers set whatsapp='0771234567' where id=sid;
 update public.proc_supplier_portal_links set revoked_at=clock_timestamp() where id=lid;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','service_role',true);
 begin perform public.proc_portal_session_v1(token,repeat('c',64),'read');raise exception 'TEST revoked session';exception when insufficient_privilege then null;end;
 assert public.proc_portal_otp_request_v1(token,'0771234567',gen_random_uuid(),repeat('a',64)) is null,'Revoked link received code';
 perform set_config('request.jwt.claim.sub',admin_v::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 assert public.proc_supplier_document_settings_v1('{"po":{"name":"G-E-N","title":"SUPPLY ORDER","caption":"{company_name} {po_number}"},"rfq":{"name":"G-E-N"}}')->'po'->>'name'='G-E-N','Shared branding not saved';
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','service_role',true);
 assert public.proc_supplier_document_settings_v1()->'rfq'->>'name'='G-E-N','Worker cannot read branding';
 begin perform public.proc_supplier_document_settings_v1('{}');raise exception 'TEST worker changed branding';exception when insufficient_privilege then null;end;
end $test$;
rollback;
